      "letra": "Si tú eres cristiano, di amén, amén.\n(2)\n\nSi tú eres cristiano, testifica con tu\nvida, si tú eres cristiano, di amén,\namén.\n\nSi tú eres cristiano, gloria a\nDios...(Con las palmas... con los pies...\ntodo junto... al revés... ida y vuelta...)"
