      "titulo_original": "SI UN MERCEDARIO MISIONA",
      "seccion": "Animación",
      "seccion_codigo": "ANI",
      "letra": "Si un mercedario misiona y\nmisiona noche y día, a todos\nevangeliza con la ayuda de María.\n(2)\n\nSomos testigos de María Mamá,\nque nos transforma la vida. (2)\n\nMercedarios por aquí,\nmercedarios por allá, nos vamos\ntodos juntos para evangelizar. (2)\n\nBasta de secularismo que si Dios\nno nos uniera, encima que somos\npocos, nos devoran los de afuera.\n(2)"
