      "titulo_original": "YA LLEGÓ, YA LLEGÓ",
      "seccion": "Animación",
      "seccion_codigo": "ANI",
      "letra": "Ya llegó, ya llegó, el Espíritu Santo,\nya llegó. (2)\n\nLo siento en las manos, lo siento en\nlos pies, lo siento en el alma  y en\ntodo mi ser.\n\nAquel que caminó sobre las aguas. (2)\nEstá aquí, está a mi lado. (2) Es como\nun rayo, cayendo sobre mí. (2) Ay que\nquema, que quema, que quema, ah.\n(2)"
